-- 分解界面说明文字
_Decompose_tip_info = "1.点击“+”进入选择介面，每次可最多选择5个忍者、装备、宝物或时装进行分解。\r\n2.只可分解4星及以上未成长的忍者，分解后返还所有升级花费并获得兽魂。\r\n3.可分解3星和4星装备，分解后返还所有升级花费并获得觉醒书。\r\n4.可分解5星装备，分解后返还所有升级花费并获得橙装铸造材料。\r\n5.只可分解5星宝物，分解后可获得灵气精华并返还所有强化经验(返还的经验在分解获得的蓝色经验宝物中)\r\n6.分解时装可获得时装精华\r\n7.分解后，所分解的忍者、装备、宝物或时装将会消失。"


-- 退化界面说明文字
_Regeneration_tip_info = "1.点击“+”进入选择介面，每次只可选择1个忍者、装备、宝物或时装进行退化。\r\n2.可退化强化等级在2级及以上的4星忍者和5星忍者，退化后返还所有花费(成长所消耗的铜币不返还)，退化后的忍者恢复成长等级为0阶，强化等级为1级。\r\n3.可退化6星忍者，退化后变为5星+7，等级不变，并返还成长和橙色成长所消耗的所有铜币及材料。\r\n4.只可退化5星且强化等级大于0的装备，退化后返还所有强化费用，并根据洗炼属性返还觉醒书。\r\n5.只可退化强化等级大于0的时装，退化后返还所有强化费用和时装精华。\r\n6.只可退化4星及以上，强化过的宝物，退化后返还所有升级花费，并根据宝物等级返还经验宝物和觉醒宝物\r\n7.每次退化需要花费一定铜币。"


-- 灵异探险界面的说明文字
_Divine_explain_tip_info = "1.点亮靶心图表案上的所有图案或点击任何图案都可以获得星数奖励。\r\n\r\n2.通过获得的星数可兑换奖励，星数越多兑换的奖励越多。\r\n\r\n3.每日凌晨0点重置探险次数、当前星数及奖励。"

-- 限时队长级说明文字
_Limited_hero_tip_info = "1.在活动介面中使用免费抽取或者铜币抽取忍者即可获得10积分。\r\n2.每累积获得150积分，即可获得1次免费铜币抽取次数。\r\n3.每次抽取可随机获得4星或5星忍者，5星忍者中包含限时活动忍者。\r\n4.活动结束时，根据积分排名，将会发放排名奖励。\r\n5.玩家每达到1000积分时必定抽中当前限时队长。\r\n6.积分达到60分的玩家将额外获得：10个金经验兽，铜币20万，500个成长石(该奖励与排名奖励可同时获得)\r\n活动结束的当天内奖励即会发放，通过奖励中心领取。"

-- 超级变变变说明文字(限时兑换)
_Super_change_tip_info = "1.活动期间内，玩家可使用指定的物品进行兑换，获得新的物品；\r\n2.可使用未强化过的装备或宝物进行兑换；\r\n3.兑换后会失去原有物品并获得兑换后的新物品。"

-- 分段折扣说明文字
_Divide_sell_tip_info = "1.活动期间根据全服购买的指定道具数量对该道具进行打折。\r\n2.当指定道具消耗数量达到指定数量时，商店内出售的该道具价格也将相应的发生变化。\r\n"

-- 跨服幸运大转盘说明文字
_Luck_turntable_tip_info = "1.活动期间使用免费或铜币转动幸运大转盘都可获得1积分，活动结束后会根据积分排名发放对应奖励；\r\n2.免费次数不会累加，免费次数使用后12小时会恢复；\r\n3.活动期间使用免费或铜币转动幸运大转盘都会增加一点次数奖励进度条，达到对应次数可立刻领取奖励；\r\n4.每天有5次免费刷新机会可刷新转盘上的奖励，免费次数用完后可使用铜币刷新，当玩家抽中高级道具时会强制刷新转盘；\r\n5.免费刷新或使用铜币刷新都有机会刷出高级限量道具(限量道具售光后无法再刷出)；\r\n6.免费转动或使用铜币转动幸运大转盘都有机会获得幸运大奖；\r\n7.系统会将玩家转动转盘消耗的铜币按一定比例累加到幸运大奖奖池，累加无上限；\r\n8.当玩家转到幸运大奖后，将会独得奖池内一定比例的铜币大奖；\r\n9.幸运大转盘资料所有伺服器互通。"

-- 灵王宫说明文字
_spirite_palace_tip_info = "1.每天可获得一次免费重置机会(不可累加)；\r\n2.灵王宫共有五层，每层达到可移动次数上限后就出现下一层入口，达到第五层终点即完成本轮探险；\r\n3.点击岔道口的事件图示可以查看事件说明，点击移动可触发该事件，或直接点击下方箭头进行移动；\r\n4.每触发一个事件都会获得一定的积分，积分可在灵王宫商店兑换道具；\r\n5.每次移动都会消耗1点行动力，行动力为0时不可再移动；\r\n6.首次进入灵王宫或重置后，会根据玩家当前阵容确定当前探险阵型，探险阵型一旦确定，本次探险过程中将无法进行改变；\r\n7.首次进入灵王宫或重置后，会根据玩家当前阵容所有忍者生命之和的三倍生成一条血槽，玩家在探险过程中会遭遇战斗，战斗结束后会根据忍者的损血量消耗血槽进行补充，如果血槽降到0便无法继续探险。"

-- 跨服战说明文字
_cross_server_tip_info = "【更新战斗资讯】\r\nA)战斗资讯\r\n是指跟玩家战斗相关的资料，即上阵忍者、装备、鬼道、阵型等所有可以影响玩家战斗强弱的相关资讯。\r\nB)更新战斗资讯\r\n玩家每次变动战斗资讯后需要点击“更新战斗资讯”来向跨界争霸战游戏伺服器上传最新的战斗资讯，否则游戏伺服器上的玩家战斗资讯不会改变。\r\n【跨界争霸战规则】\r\nA)先手规则\r\n战斗力高的玩家为先手\r\nB)海选赛规则\r\n1、瀞灵廷组海选赛规则\r\n1)随机分配对手，每场1局，每场间隔10分钟\r\n2)玩家不会再遇到已出局的对手\r\n3)如果玩家累积失败3场则被淘汰出局，直至决出最后32强\r\n4)玩家可以在我的资讯中“我的战绩”处查看自己的战绩\r\n2、流魂街组海选赛规则\r\n1)瀞灵廷组海选赛结束后，去除瀞灵廷组出线的选手，其他玩家进行流魂街组海选赛\r\n2)随机分配对手，每场1局，每场间隔10分钟\r\n3)玩家不会再遇到已出局的对手\r\n4)如果玩家累积失败3场则被淘汰出局，直至决出最后32强，海选结束\r\n5)玩家可以在我的资讯中“我的战绩”处查看自己的战绩\r\nC)晋级赛规则\r\n1、海选赛出线的瀞灵廷32强和流魂街32强分成16组，以每组2人进行5局3胜的比赛，获得3场胜利的玩家晋级，每局间隔20分钟\r\n2、每场晋级赛间隔1天\r\n3、瀞灵廷组和流魂街组分别决出各自组的冠军\r\n4、进入晋级赛的玩家自动进入跨服跨界争霸赛的海选\r\n【跨服跨界争霸赛规则】\r\nA)先手规则\r\n战斗力高的玩家为先手\r\nB)海选赛规则\r\n1、瀞灵廷组海选赛规则\r\n1)随机分配对手，每场1局，每场间隔10分钟\r\n2)玩家不会再遇到已出局的对手\r\n3)如果玩家累积失败3场则被淘汰出局，直至决出最后32强\r\n4)玩家可以在我的资讯中“我的战绩”处查看自己的战绩\r\n2、流魂街组海选赛规则\r\n1)瀞灵廷组海选赛结束后，去除瀞灵廷组出线的选手，其他玩家进行流魂街组海选赛\r\n2)随机分配对手，每场1局，每场间隔10分钟\r\n3)玩家不会再遇到已出局的对手\r\n4)如果玩家累积失败3场则被淘汰出局，直至决出最后32强，海选结束\r\n5)玩家可以在我的资讯中“我的战绩”处查看自己的战绩\r\nC)晋级赛规则\r\n1、海选赛出线的瀞灵廷32强和流魂街32强分成16组，以每组2人进行5局3胜的比赛，获得3场胜利的玩家晋级，每局间隔20分钟\r\n2、每场晋级赛间隔1天\r\n3、瀞灵廷组和流魂街组分别决出各自组的冠军\r\n4、跨服跨界争霸赛瀞灵廷组冠军所在伺服器所有玩家可获得礼包奖励\r\n【助威规则】\r\n晋级赛阶段，每场晋级赛玩家只可为1名玩家助威，被助威的玩家如果进入下一轮比赛，则助威的玩家可获得助威奖励。每场晋级赛结束后发放助威奖励，当奖励发放完毕后，可进行下一场晋级赛的助威。"

-- 副队长说明文字
_vice_captain_tip_info = "1.上阵中的副队长，每隔一段时间获得一定经验；\r\n2.只有上阵中的副队长才可进行出战操作，出战的副队长可在战前将自身技能属性提供给上阵忍者；\r\n3.一次只能出战一名副队长；\r\n4.培养可增加副队长经验，当副队长升到一定等级时可获得技能点；\r\n5.技能点可用来开启技能槽、领悟技能、升级技能。"

--侵略者帮助奖励文字
_betray_army_reward_tip_info = "1.光丘守护可获得功勋奖励，主要是大量铜币、晶片石和橙色经验宝物。\r\n2.光丘守护还可获得战功，战功可在战功商店购买稀有忍者和晶片石。"

--侵略者帮助功勋文字
_betray_army_exploit_tip_info = "1.35级后，每次挑战主线副本和精英副本都有概率发现侵略者，可以单独或邀请好友一起光丘守护。\r\n2.每次光丘守护会获得功勋值，伤害越高功勋值越多，忍者每成长+1对侵略者伤害提升2.5倍！\r\n3.若击杀侵略者，发现侵略者的玩家和给予最后一击的玩家都可获得铜币奖励。"

--侵略者帮助战功文字
_betray_army_credit_tip_info = "1.攻打侵略者时，每消耗一个挑战书，都可获得50战功。\r\n2.若进入光丘守护的每日功勋榜和每日伤害榜前200名，还可获得额外的排名战功奖励。\r\n3.每天12:00-14:00怒攻只消耗1个挑战书，18:00-20:00攻打侵略者功勋翻倍。"

--组织资源抢夺帮助信息
_capture_resource_tip_info = "1.击败建筑守卫者可占领该建筑，并可获得资源产出奖励；\r\n2.每名玩家可同时占领多个建筑，相邻的建筑可获得资源产出加成；\r\n3.每个建筑有对应的占领条件，占领建筑的阵容为临时组建阵容，跟原有阵容相互独立；\r\n4.可派出原阵容中已上阵的忍者，不会计算装备和宝物属性，缘分会按照新的上阵情况重新计算；\r\n5.占领成功后，所派出的忍者将成为建筑守卫，不可中途更换；\r\n6.攻打建筑或占领建筑可获得积分，每周二和每周五中午12点会根据积分排名发放奖励，并清空积分；\r\n7.攻打建筑无论胜利失败可获得5积分，占领建筑后每分钟可获得1积分(占领结束时根据占领时间获得)；\r\n8.排名奖励需要玩家自行进入奖励页面领取，奖励会保存到下一次排行结算，结算时会删除未领取的奖励(积分为0的玩家无法获得奖励)。"

---组织战帮助信息
_union_fight_tip_info = "报名阶段：\r\n1.周三3点开启报名；\r\n2.加入组织48小时的成员才能参与组织战；\r\n3.组织战为跨服战斗，会根据组织战力匹配对手。\r\n\r\n准备阶段：\r\n1.周四3点开启准备阶段；\r\n2.首领和副首领可部署防守阵型；\r\n3.组织成员在前后城各拥有一个防守格；\r\n4.暗格在被攻击前处于资讯不明状态。\r\n\r\n战斗阶段：\r\n1.周五3点开启战斗，22点结算战斗；\r\n2.每人3次尝试进攻机会，2次击杀次数；\r\n3.守卫为1的据点进入【失守】状态，可被通过；\r\n4.守卫为0的据点进入【攻陷】状态，可取得积分；\r\n5.特殊据点包含额外奖励，攻陷该据点后可领取；\r\n6.结算时积分高的组织获胜，如果积分相同，战力低的组织获胜；\r\n7.胜利或失败的组织都会获得奖励，失败的奖励是胜利的一半。"


