	"3.组织等级提升后可以开启新的组织副本，提高建设进度奖励，在组织商店中也会开放更多奖励道具。",
	"4.成员可以从组织建设和组织副本中获得组织贡献，组织贡献可以在组织商店中购买各种道具。",
	"5.组织贡献：可透过组织副本和组织捐献获得，可在组织商店购买道具。",
	"6.组织首领：组织成员少于10人时，首领可解散组织；首领最多可任命2名副首领，首领和副首领均享有以下权限：审核新成员、踢出成员、编辑组织公告和宣言等。",
	"7.组织成员：加入后24小时内不可被踢出。",
	"8.创建组织7日内，组织成员数不足3人，并且组织等级为1级时，组织会自动解散。",
	"组织建设",
	"1.建设模式：初级建设、普通建设和高级建设。组织成员每天可选择一种模式进行建设。",
	"2.建设过程中，有机率触发增益，获得150%组织贡献和组织经验（额外加成不计入进度）",
	"3.组织进度到达对应要求后，全体组织成员均可领取建设进度奖励。",
	"4.组织等级越高，建设进度奖励越丰厚。",
	"5.需注意，每天24:00系统会自动清空当天的建设进度奖励。",
	"6.每天的建设次数不能超过组织成员数上限。",
}



